"""Monthly sector allocation with a penalty for variance relative to SPY."""

import gzip
import hashlib
import json
import signal
from dataclasses import asdict, dataclass, replace
from datetime import datetime
from io import BytesIO
from pathlib import Path

import numpy as np
import pandas as pd
import yaml
from pandas.tseries.holiday import (
    AbstractHolidayCalendar,
    GoodFriday,
    Holiday,
    USLaborDay,
    USMartinLutherKingJr,
    USMemorialDay,
    USPresidentsDay,
    USThanksgivingDay,
    nearest_workday,
    sunday_to_monday,
)
from scipy.optimize import minimize


ROOT = Path(__file__).resolve().parent
SESSIONS_PER_YEAR = 252
TRADE_TOLERANCE = 1e-8
SECTOR_FUNDS = {"XLB", "XLC", "XLE", "XLF", "XLI", "XLK", "XLP", "XLRE", "XLU", "XLV", "XLY"}


class NyseHolidays(AbstractHolidayCalendar):
    rules = [
        Holiday("New Year's Day", month=1, day=1, observance=sunday_to_monday),
        USMartinLutherKingJr,
        USPresidentsDay,
        GoodFriday,
        USMemorialDay,
        Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01", observance=nearest_workday),
        Holiday("Independence Day", month=7, day=4, observance=nearest_workday),
        USLaborDay,
        USThanksgivingDay,
        Holiday("Christmas", month=12, day=25, observance=nearest_workday),
    ]


@dataclass(frozen=True)
class Parameters:
    lookback_days: int
    risk_aversion: float
    competition_weight: float
    cost_bps: float
    slippage_bps: float
    cash_buffer_bps: float

    def __post_init__(self):
        if type(self.lookback_days) is not int or self.lookback_days < 2:
            raise ValueError("lookback_days must be an integer of at least two")
        if not np.isfinite(self.risk_aversion) or self.risk_aversion <= 0:
            raise ValueError("risk_aversion must be finite and positive")
        if not 0 <= self.competition_weight <= 1:
            raise ValueError("competition_weight must be between zero and one")
        if not (self.cost_bps >= 0 and self.slippage_bps >= 0 and self.trade_rate < 1):
            raise ValueError("Cost and slippage must be nonnegative and total under 10000 bps")
        if not 0 < self.cash_buffer_bps < 10_000:
            raise ValueError("cash_buffer_bps must be positive and under 10000 bps")

    @property
    def trade_rate(self):
        return (self.cost_bps + self.slippage_bps) / 10_000

    @property
    def cash_buffer(self):
        return self.cash_buffer_bps / 10_000


def expected_sessions(history_start, end):
    if history_start < pd.Timestamp("2006-01-01") or end > pd.Timestamp("2025-12-31"):
        raise ValueError("NYSE calendar coverage is 2006 through 2025")
    holidays = NyseHolidays().holidays(start=history_start, end=end)
    # Full-day closures for the Ford, Bush and Carter mourning days and Hurricane Sandy.
    closures = pd.to_datetime(["2007-01-02", "2012-10-29", "2012-10-30", "2018-12-05", "2025-01-09"])
    return pd.bdate_range(history_start, end).difference(holidays.union(closures))


def check_closes(prices, tickers, risk_free, sessions, start):
    if not isinstance(prices.index, pd.DatetimeIndex) or prices.empty:
        raise ValueError("Yahoo Finance returned no dated adjusted closes")
    if prices.index.has_duplicates or not prices.index.is_monotonic_increasing:
        raise ValueError("Expected unique adjusted closes in chronological order")
    if not prices.index.equals(sessions):
        missing = sessions.difference(prices.index)
        unexpected = prices.index.difference(sessions)
        raise ValueError(
            f"Yahoo Finance dates differ from NYSE sessions. "
            f"Missing ({len(missing)}): {missing[:5].strftime('%Y-%m-%d').tolist()}; "
            f"unexpected ({len(unexpected)}): {unexpected[:5].strftime('%Y-%m-%d').tolist()}"
        )

    first_scored = prices.index.searchsorted(start)
    if first_scored == len(prices):
        raise ValueError("The configured scoring period has no NYSE sessions")
    if first_scored == 0:
        raise ValueError("At least one pre-sample close is required for daily returns")
    for ticker in tickers:
        ticker_closes = prices[ticker]
        if ticker == risk_free:
            ticker_closes = ticker_closes.iloc[first_scored - 1:]
        invalid = ~np.isfinite(ticker_closes) | (ticker_closes <= 0)
        if invalid.any():
            date = ticker_closes.index[invalid][0].date()
            raise ValueError(f"Missing or invalid adjusted close for {ticker} on {date}")


def load_closes(tickers, risk_free, history_start, start, end, settings, config_path="config.yaml"):
    sessions = expected_sessions(history_start, end)
    data = settings.get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    snapshot = gzip.decompress(bytes(blob))
    digest = hashlib.sha256(snapshot).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the market snapshot in {Path(config_path).name}: {digest}."
        )
    with BytesIO(snapshot) as stream:
        fetched_at = stream.readline().decode("utf-8").strip()
        datetime.fromisoformat(fetched_at)
        prices = pd.read_csv(stream, index_col="date", parse_dates=["date"])
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: yfinance auto_adjust snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); the script does not call yfinance or read data_cache."
    )
    print(f"Input SHA-256: {hashlib.sha256(snapshot.partition(b'\n')[2]).hexdigest()}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    prices = prices.reindex(columns=tickers)
    check_closes(prices, tickers, risk_free, sessions, start)
    return prices, fetched_at


def optimal_weights(relative_window, risk_aversion):
    mean = relative_window.mean(axis=0) * SESSIONS_PER_YEAR
    covariance = np.atleast_2d(np.cov(relative_window, rowvar=False)) * SESSIONS_PER_YEAR
    n_assets = len(mean)
    ones = np.ones(n_assets)

    def objective(weights):
        variance = weights @ covariance @ weights
        return 0.5 * risk_aversion * variance - mean @ weights

    result = minimize(
        objective,
        ones / n_assets,
        jac=lambda weights: risk_aversion * (covariance @ weights) - mean,
        method="SLSQP",
        bounds=[(0, 1)] * n_assets,
        constraints={"type": "eq", "fun": lambda weights: weights.sum() - 1, "jac": lambda weights: ones},
        options={"ftol": 1e-12, "maxiter": 200},
    )
    if not result.success or not np.isfinite(result.x).all() or abs(result.x.sum() - 1) > 1e-8:
        raise RuntimeError(f"Sector optimization failed: {result.message}")
    weights = result.x.clip(0, 1)
    weights[weights < TRADE_TOLERANCE] = 0
    return weights / weights.sum()


def rebalance_targets(asset_returns, peer_returns, start, lag, spec):
    dates = asset_returns.index
    month_openings = np.flatnonzero(dates.to_period("M")[1:] != dates.to_period("M")[:-1]) + 1
    # Fully invested weights let each asset be expressed in benchmark-relative returns.
    relative = asset_returns.to_numpy() - spec.competition_weight * peer_returns.to_numpy()[:, None]
    targets = {}
    for opening in month_openings:
        fill = opening + lag - 1
        if fill >= len(dates) or dates[fill] < start:
            continue
        first_return = opening - spec.lookback_days
        if first_return < 1:
            raise ValueError(f"Insufficient signal history for {dates[opening - 1].date()}")
        # The last return ends at the prior month's final close. The fill is a later close.
        targets[dates[fill]] = optimal_weights(relative[first_return:opening], spec.risk_aversion)
    return targets


def size_positions(positions, previous_closes, cash, target, spec):
    invested_value = positions @ previous_closes
    desired_value = (cash + invested_value) * (1 - spec.cash_buffer)
    # Budget for fees up to a full sale and repurchase at the sizing prices.
    fee_reserve = spec.trade_rate * (invested_value + desired_value)
    target_value = max(0.0, desired_value - fee_reserve)
    return target * target_value / previous_closes


def settle_orders(planned_changes, fill_closes, cash, trade_rate, date):
    fill_values = planned_changes * fill_closes
    gross_traded_value = np.abs(fill_values).sum()
    remaining_cash = cash - fill_values.sum() - trade_rate * gross_traded_value
    if not np.isfinite(remaining_cash):
        raise ArithmeticError(f"Simulated fill on {date.date()} would leave non-finite cash")
    if remaining_cash < 0:
        raise ArithmeticError(f"Simulated fill on {date.date()} would leave negative cash: {remaining_cash:.8g}")
    return remaining_cash, gross_traded_value


def simulate(closes, risk_free_returns, start, targets, spec):
    first_scored = closes.index.searchsorted(start)
    if first_scored == 0:
        raise ValueError("Simulation requires a close before the first scored session")
    scored_dates = closes.index[first_scored:]
    prices = closes.to_numpy()
    positions = np.zeros(closes.shape[1])
    cash = 1.0
    rows = []
    for offset, date in enumerate(scored_dates, start=first_scored):
        previous_prices = prices[offset - 1]
        previous_value = positions @ previous_prices + cash
        target = targets.get(date)
        if target is not None:
            # Fix the position sizes and quantity changes using only prior-close inputs.
            next_positions = size_positions(positions, previous_prices, cash, target, spec)
            planned_changes = next_positions - positions
            next_positions.setflags(write=False)
            planned_changes.setflags(write=False)

        fill_prices = prices[offset]
        cash_growth = 1 + risk_free_returns.at[date]
        if not np.isfinite(cash_growth) or cash_growth <= 0:
            raise ValueError(f"Invalid BIL cash return on {date.date()}")
        cash *= cash_growth
        turnover = 0.0
        trades = 0
        if target is not None:
            value_before_fill = positions @ fill_prices + cash
            cash, gross_traded_value = settle_orders(planned_changes, fill_prices, cash, spec.trade_rate, date)
            positions = next_positions
            turnover = gross_traded_value / value_before_fill
            trades = np.count_nonzero(planned_changes)
        closing_value = positions @ fill_prices + cash
        rows.append((closing_value / previous_value - 1, turnover, trades))
    return pd.DataFrame(rows, index=scored_dates, columns=["return", "turnover", "n_trades"])


def sharpe(returns):
    if len(returns) < 2 or np.ptp(returns) <= 4 * np.finfo(float).eps:
        return None
    volatility = returns.std(ddof=1)
    return float(np.sqrt(SESSIONS_PER_YEAR) * returns.mean() / volatility) if volatility > 0 else None


def metrics(daily_results, risk_free_returns):
    returns = daily_results["return"].to_numpy()
    growth = np.r_[1.0, np.cumprod(1 + returns)]
    excess = returns - risk_free_returns.loc[daily_results.index].to_numpy()
    return {
        "cagr": float(growth[-1] ** (SESSIONS_PER_YEAR / len(returns)) - 1) if len(returns) else None,
        "ann_vol": float(returns.std(ddof=1) * np.sqrt(SESSIONS_PER_YEAR)) if len(returns) > 1 else None,
        "sharpe": sharpe(returns),
        "sharpe_excess": sharpe(excess),
        "max_drawdown": float((growth / np.maximum.accumulate(growth) - 1).min()) if len(returns) else None,
        "total_return": float(growth[-1] - 1) if len(returns) else None,
        "turnover": float(daily_results["turnover"].sum()),
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def period_metrics(daily_results, risk_free_returns, split):
    before_split = daily_results.index < split
    return {
        "is": metrics(daily_results.loc[before_split], risk_free_returns),
        "oos": metrics(daily_results.loc[~before_split], risk_free_returns),
        "full": metrics(daily_results, risk_free_returns),
    }


def main():
    config = yaml.safe_load((ROOT / "config.yaml").read_text(encoding="utf-8"))
    universe, peer, risk_free = config["universe"], config["benchmark"], config["risk_free"]
    if not universe or len(universe) != len(set(universe)) or not set(universe) <= SECTOR_FUNDS:
        raise ValueError("universe must contain distinct Select Sector SPDR funds")
    if (peer, risk_free) != ("SPY", "BIL"):
        raise ValueError("This strategy uses SPY as benchmark and BIL as its cash proxy")

    history_start, start, end, split = (
        pd.Timestamp(config[key]) for key in ("history_start", "start", "end", "oos_start")
    )
    today = pd.Timestamp.now(tz="America/New_York").normalize().tz_localize(None)
    if not history_start < start < split <= end < today:
        raise ValueError("Expected history_start < start < oos_start <= end before today in New York")
    lag = config["signal_lag_sessions"]
    if type(lag) is not int or lag < 1:
        raise ValueError("signal_lag_sessions must be a positive integer")

    official = Parameters(**config["parameters"])
    sensitivities = {label: replace(official, **changes) for label, changes in config["robustness"].items()}
    if len(set(sensitivities.values()) | {official}) != len(sensitivities) + 1:
        raise ValueError("Each robustness case must use a distinct parameter combination")

    tickers = sorted([*universe, peer, risk_free])
    closes, fetched_at = load_closes(
        tickers, risk_free, history_start, start, end, config, str(ROOT / "config.yaml")
    )
    print(f"DATA_FETCHED_AT: {fetched_at}")
    print("PRICE_ADJUSTMENT: yfinance auto_adjust total-return closes (dividends and splits)")
    returns = closes.pct_change(fill_method=None)
    scored = returns.loc[start:]
    in_sample = returns.loc[returns.index < split]
    is_scored = in_sample.loc[start:]

    print("ROBUSTNESS (IS only)")
    for label, spec in sensitivities.items():
        targets = rebalance_targets(in_sample[universe], in_sample[peer], start, lag, spec)
        daily_results = simulate(closes.loc[in_sample.index, universe], is_scored[risk_free], start, targets, spec)
        result = {"parameters": asdict(spec), "is": metrics(daily_results, is_scored[risk_free])}
        print(f"  {label}: {json.dumps(result, allow_nan=False)}")

    targets = rebalance_targets(returns[universe], returns[peer], start, lag, official)
    daily_results = simulate(closes[universe], scored[risk_free], start, targets, official)
    benchmark_entry = min(targets, default=scored.index[0])
    benchmark_targets = {benchmark_entry: np.ones(1)}
    benchmark_results = simulate(closes[[peer]], scored[risk_free], start, benchmark_targets, official)
    official_summary = period_metrics(daily_results, scored[risk_free], split)
    benchmark_summary = period_metrics(benchmark_results, scored[risk_free], split)

    print(f"PARAM_COMBOS_TRIED: {1 + len(sensitivities)}")
    print(f"OFFICIAL_PARAMETERS: {json.dumps(asdict(official), allow_nan=False)}")
    for period, result in official_summary.items():
        print(f"{period.upper()}: {json.dumps(result, allow_nan=False)}")
        print(f"BENCHMARK {peer} {period.upper()}: {json.dumps(benchmark_summary[period], allow_nan=False)}")
    results = {
        "strategy": config["strategy"],
        "data_range": {"start": scored.index[0].date().isoformat(), "end": scored.index[-1].date().isoformat()},
        **official_summary,
        "benchmark": {"ticker": peer, **benchmark_summary},
    }
    print("RESULTS_JSON: " + json.dumps(results, allow_nan=False))


if __name__ == "__main__":
    signal.alarm(9 * 60)
    main()
